-- Preserve existing role access while expanding legacy permissions to CRUD.
UPDATE "Role" SET permissions = ARRAY(SELECT DISTINCT p FROM unnest(permissions || ARRAY['transactions.read','categories.read','budgets.read','goals.read','users.read','roles.read']::text[] || CASE WHEN 'transactions.write' = ANY(permissions) THEN ARRAY['transactions.create','transactions.update','transactions.delete']::text[] ELSE ARRAY[]::text[] END || CASE WHEN 'categories.write' = ANY(permissions) THEN ARRAY['categories.create','categories.update','categories.delete']::text[] ELSE ARRAY[]::text[] END || CASE WHEN 'budgets.write' = ANY(permissions) THEN ARRAY['budgets.create','budgets.update','budgets.delete']::text[] ELSE ARRAY[]::text[] END || CASE WHEN 'goals.write' = ANY(permissions) THEN ARRAY['goals.create','goals.update','goals.delete']::text[] ELSE ARRAY[]::text[] END || CASE WHEN 'users.manage' = ANY(permissions) THEN ARRAY['users.create','users.update','users.delete']::text[] ELSE ARRAY[]::text[] END || CASE WHEN 'roles.manage' = ANY(permissions) THEN ARRAY['roles.create','roles.update','roles.delete']::text[] ELSE ARRAY[]::text[] END || CASE WHEN 'reports.read' = ANY(permissions) THEN ARRAY['reports.export']::text[] ELSE ARRAY[]::text[] END) AS p WHERE p NOT IN ('transactions.write','categories.write','budgets.write','goals.write','users.manage','roles.manage'));
UPDATE "Role" SET permissions = ARRAY['transactions.read','transactions.create','transactions.update','transactions.delete','categories.read','categories.create','categories.update','categories.delete','budgets.read','budgets.create','budgets.update','budgets.delete','goals.read','goals.create','goals.update','goals.delete','users.read','users.create','users.update','users.delete','roles.read','roles.create','roles.update','roles.delete','reports.read','reports.export']::text[] WHERE name = 'Owner';
